param([switch]$Apply)
$ErrorActionPreference='Stop';$root=[System.IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$targets=Get-ChildItem -LiteralPath $root -Directory -Recurse -Force -ErrorAction SilentlyContinue|Where-Object{$_.Name -in @('__pycache__','.pytest_cache')};$actions=$targets|ForEach-Object{[ordered]@{target=$_.FullName;action=$(if($Apply){'quarantine'}else{'would-quarantine'})}};if($Apply -and $targets){$quarantine=Join-Path $root ('artifacts\autonomy-quarantine\'+(Get-Date -Format 'yyyyMMddTHHmmssZ'));New-Item -ItemType Directory -Path $quarantine -Force|Out-Null;foreach($target in $targets){$resolved=[System.IO.Path]::GetFullPath($target.FullName);if(-not $resolved.StartsWith($root+[System.IO.Path]::DirectorySeparatorChar,[System.StringComparison]::OrdinalIgnoreCase)){throw 'Reset target escaped repository.'};Move-Item -LiteralPath $resolved -Destination (Join-Path $quarantine (([guid]::NewGuid().ToString('N'))+'-'+$target.Name))}};[ordered]@{schemaVersion=1;applied=[bool]$Apply;destructiveDelete=$false;actions=$actions}|ConvertTo-Json -Depth 6 -Compress
